import json, glob, os
base='/home/lijian/.claude/projects/-home-lijian-project-open-vela/20f94ca5-02c5-44f4-a5b0-96f6983f62d0/subagents'
for p in glob.glob(base+'/*.jsonl'):
    rows=[]
    with open(p, encoding='utf-8') as f:
        for line in f:
            try: rows.append(json.loads(line))
            except Exception: pass
    print('\n###', os.path.basename(p), 'records', len(rows))
    for r in rows[-5:]:
        typ=r.get('type') or r.get('role')
        msg=r.get('message', r)
        role=msg.get('role') if isinstance(msg,dict) else None
        content=msg.get('content') if isinstance(msg,dict) else None
        if isinstance(content,list):
            parts=[]
            for c in content:
                if isinstance(c,dict):
                    t=c.get('type')
                    if t=='text': parts.append(c.get('text','')[:500].replace('\n',' '))
                    elif t=='tool_use': parts.append('TOOL '+c.get('name',''))
                    elif t=='tool_result': parts.append('RESULT')
            content=' | '.join(parts)
        print(typ, role, str(content)[:800])
