for p in glob.glob(base+'/*.jsonl'):
    events=[]
    with open(p, encoding='utf-8') as f:
        for line in f:
            try:r=json.loads(line)
            except:continue
            m=r.get('message')
            if not isinstance(m,dict): continue
            for c in m.get('content',[]) if isinstance(m.get('content'),list) else []:
