 static uint32_t bk7258_ap_mbox_receive(void)
 {
   volatile uint32_t *mbox = bk7258_ap_mbox(BK7258_MBOX1_BASE);
   volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
   uint32_t event = BK7258_AP_EVENT_NONE;

