147	 ****************************************************************************/
148	
149	static void bk7258_uart_sdk_isr(uart_id_t id, void *param)
150	{
151	  struct uart_dev_s *dev = (struct uart_dev_s *)param;
152	
153	  (void)id;
154	  uart_recvchars(dev);
155	}
