157	/****************************************************************************
158	 * Name: bk7258_uart_setup
159	 ****************************************************************************/
160	
161	static int bk7258_uart_setup(struct uart_dev_s *dev)
162	{
163	  static bool initialized;
164	  struct bk7258_uart_s *priv = dev->priv;
165	  const uart_config_t config =
166	    {
167	      .baud_rate = BK7258_UART_BAUD_RATE,
168	      .data_bits = UART_DATA_8_BITS,
169	      .parity = UART_PARITY_NONE,
170	      .stop_bits = UART_STOP_BITS_1,
171	      .flow_ctrl = UART_FLOWCTRL_DISABLE,
172	      .src_clk = UART_SCLK_XTAL_26M,
173	      .rx_dma_en = UART_DMA_DISABLE,
174	      .tx_dma_en = UART_DMA_DISABLE,
175	    };
176	
177	  if (initialized)
178	    {
179	      return OK;
180	    }
181	
182	  if (bk_uart_driver_init() != BK_OK)
183	    {
184	      return -EIO;
185	    }
186	
187	  if (bk_uart_init(priv->id, &config) != BK_OK)
188	    {
189	      return -EIO;
190	    }
191	
192	  /* NuttX owns the receive ring.  Keep bytes in the hardware FIFO so the SDK
193	   * callback can hand them directly to uart_recvchars().
194	   */
195	
196	  if (bk_uart_disable_sw_fifo(priv->id) != BK_OK)
197	    {
198	      return -EIO;
199	    }
200	
201	  if (bk_uart_set_rx_full_threshold(priv->id, 1) != BK_OK)
202	    {
203	      return -EIO;
204	    }
205	
206	  priv->rxbyte = -1;
207	  initialized = true;
208	  return OK;
209	}
