226	static int bk7258_uart_attach(struct uart_dev_s *dev)
227	{
228	  struct bk7258_uart_s *priv = dev->priv;
229	  bk_err_t ret;
230	
231	  ret = bk_uart_register_rx_isr(priv->id, bk7258_uart_sdk_isr, dev);
232	  return ret == BK_OK ? OK : -EIO;
233	}
