255	/****************************************************************************
256	 * Name: bk7258_uart_rxavailable / receive
257	 ****************************************************************************/
258	
259	static bool bk7258_uart_rxavailable(struct uart_dev_s *dev)
260	{
261	  struct bk7258_uart_s *priv = dev->priv;
262	
263	  if (priv->rxbyte < 0)
264	    {
265	      uint8_t byte;
266	      int nread;
267	
268	      nread = bk_uart_read_bytes(priv->id, &byte, 1, 0);
269	      priv->rxbyte = nread == 1 ? byte : -1;
270	    }
271	
272	  return priv->rxbyte >= 0;
273	}
274	
275	static int bk7258_uart_receive(struct uart_dev_s *dev, unsigned int *status)
276	{
277	  struct bk7258_uart_s *priv = dev->priv;
278	  int ch = priv->rxbyte;
279	
280	  priv->rxbyte = -1;
281	  if (status)
282	    {
283	      *status = 0;
284	    }
285	
286	  return ch;
287	}
