320	 * Name: bk7258_uart_txint
321	 ****************************************************************************/
322	
323	static void bk7258_uart_txint(struct uart_dev_s *dev, bool enable)
324	{
325	  /* There is no TX interrupt; fake one by draining the ring synchronously
326	   * whenever the upper half enables transmission.  This makes the console
327	   * write path blocking-polled (matches the CMSDK polled fallback).
328	   */
329	
330	  if (enable)
331	    {
332	      uart_xmitchars(dev);
333	    }
334	}
