338	 ****************************************************************************/
339	
340	static bool bk7258_uart_txready(struct uart_dev_s *dev)
341	{
342	  /* bk_uart_write_bytes() waits for hardware FIFO space. */
343	
344	  (void)dev;
345	  return true;
346	}
