372	{
373		uint32_t fifo_size = CONFIG_KFIFO_SIZE;
374	//RX DMA needs bigger FIFO size when erase flash.
375	#if (CONFIG_UART_RX_DMA)
376		fifo_size = CONFIG_UART_RX_DMA_KFIFO_SIZE;
377	#endif
378	
379		if (!s_uart_rx_kfifo[id]) {
380			s_uart_rx_kfifo[id] = kfifo_alloc(fifo_size);
381			if (!s_uart_rx_kfifo[id]) {
382				UART_LOGW("uart(%d) rx kfifo alloc failed\n", id);
383				return BK_ERR_NULL_PARAM;
