152		const gpio_map_t *gpio_map = NULL;
153	
154		//special for BK7235:the GPIO ID isn't from 0~47, some of the GPIO are not exist.
155		for(int i = 0; i < sizeof(gpio_map_table)/sizeof(gpio_map_t); i++)
