186	
187		const gpio_map_t *gpio_map = NULL;
188	
189		//special for BK7235:the GPIO ID isn't from 0~47, some of the GPIO are not exist.
190		for(int i = 0; i < sizeof(gpio_map_table)/sizeof(gpio_map_t); i++)
191		{
192			if(gpio_map_table[i].id == gpio_id)
193			{
194				gpio_map = &gpio_map_table[i];
195				break;
196			}
197		}
