216			}
217		}
218	
219		// set gpio as second function mode
220		gpio_hal_output_enable(hal, gpio_id, 0);
221		gpio_hal_input_enable(hal, gpio_id, 0);
222		gpio_hal_pull_enable(hal, gpio_id, 0);
223		gpio_hal_sencond_function_enable(hal, gpio_id, 1);
