26	/* TEMP cold-reset diagnostic: emit a short raw-UART tag (e.g. "A0") so we
27	 * can see exactly which AP-start checkpoint was the last to execute before
28	 * a hang.  Uses up_putc() only — no formatter, no syslog dependency.
29	 * DELETE THIS ENTIRE HELPER AND ALL cold_ckpt() CALLS AFTER DIAGNOSIS.
30	 */
31	
32	static void cold_ckpt(const char *tag)
33	{
34	  up_putc('\r');
35	  up_putc('\n');
36	  while (*tag)
37	    {
38	      up_putc(*tag++);
39	    }
40	
41	  up_putc('\r');
42	  up_putc('\n');
43	}
