71	static inline volatile uint32_t *bk7258_ap_mbox(uint32_t base)
72	{
73	  return (volatile uint32_t *)(uintptr_t)base;
74	}
75	
76	static void bk7258_cpu2_force_reset(void)
77	{
78	  volatile uint32_t *control =
79	    (volatile uint32_t *)(uintptr_t)BK7258_SYS_CPU2_CONTROL;
80	
81	  *control &= ~BK7258_SYS_CPU2_RESET;
82	  __asm volatile ("dsb sy; isb sy" ::: "memory");
