84	
85	static void bk7258_ap_mbox_ack(volatile uint32_t *mbox)
86	{
87	  mbox[BK7258_MBOX_CLEAR_OFFSET / 4] = BK7258_MBOX_BOX0_BIT;
88	  __asm volatile ("dsb sy" ::: "memory");
89	  mbox[BK7258_MBOX_READY_OFFSET / 4] = 0;
90	  mbox[BK7258_MBOX_CLEAR_OFFSET / 4] = 0;
91	  __asm volatile ("dsb sy" ::: "memory");
92	}
93	
94	static void bk7258_ap_mbox_initialize(void)
95	{
96	  volatile uint32_t *to_ap = bk7258_ap_mbox(BK7258_MBOX0_BASE);
97	  volatile uint32_t *to_cp = bk7258_ap_mbox(BK7258_MBOX1_BASE);
98	
99	  to_ap[BK7258_MBOX_CLKRST_OFFSET / 4] = 1u;
100	  to_cp[BK7258_MBOX_CLKRST_OFFSET / 4] = 1u;
101	  to_ap[BK7258_MBOX_SENDER_OFFSET / 4] = 1u << 0;
102	  to_ap[BK7258_MBOX_RECEIVER_OFFSET / 4] = 1u << 1;
103	  to_cp[BK7258_MBOX_SENDER_OFFSET / 4] = 1u << 1;
104	  to_cp[BK7258_MBOX_RECEIVER_OFFSET / 4] = 1u << 0;
105	
106	  bk7258_ap_mbox_ack(to_ap);
107	  bk7258_ap_mbox_ack(to_cp);
108	}
109	
110	static void bk7258_ap_mbox_send(uint32_t event)
111	{
112	  volatile uint32_t *mbox = bk7258_ap_mbox(BK7258_MBOX0_BASE);
113	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
114	
115	  if ((mbox[BK7258_MBOX_READY_OFFSET / 4] &
116	       BK7258_MBOX_BOX0_BIT) != 0)
117	    {
118	      bk7258_ap_mbox_ack(mbox);
119	    }
120	
121	  mbox[BK7258_MBOX_PARAM0_OFFSET / 4] = BK7258_AP_DOORBELL_MAGIC;
122	  mbox[BK7258_MBOX_PARAM1_OFFSET / 4] = event;
123	  mbox[BK7258_MBOX_PARAM2_OFFSET / 4] = state->generation;
124	  mbox[BK7258_MBOX_PARAM3_OFFSET / 4] = state->command;
125	  __asm volatile ("dmb sy" ::: "memory");
126	  mbox[BK7258_MBOX_READY_OFFSET / 4] = BK7258_MBOX_BOX0_BIT;
127	  state->cp_to_ap_doorbells++;
128	  __asm volatile ("dsb sy; sev" ::: "memory");
129	}
130	
131	static uint32_t bk7258_ap_mbox_receive(void)
132	{
133	  volatile uint32_t *mbox = bk7258_ap_mbox(BK7258_MBOX1_BASE);
134	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
135	  uint32_t event = BK7258_AP_EVENT_NONE;
136	
137	  if ((mbox[BK7258_MBOX_READY_OFFSET / 4] &
138	       BK7258_MBOX_BOX0_BIT) != 0)
139	    {
140	      if (mbox[BK7258_MBOX_PARAM0_OFFSET / 4] ==
141	          BK7258_AP_DOORBELL_MAGIC &&
142	          mbox[BK7258_MBOX_PARAM2_OFFSET / 4] == state->generation)
143	        {
144	          event = mbox[BK7258_MBOX_PARAM1_OFFSET / 4];
145	        }
146	
147	      bk7258_ap_mbox_ack(mbox);
148	    }
149	
150	  return event;
151	}
152	
153	static void bk7258_ap_state_prepare(void)
154	{
155	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
156	  uint32_t generation = 1;
157	
158	  if (state->magic == BK7258_AP_BOOT_STATE_MAGIC &&
159	      state->version == BK7258_AP_BOOT_STATE_VERSION)
160	    {
161	      generation = state->generation + 1;
162	    }
163	
164	  memset((void *)(uintptr_t)state, 0,
165	         sizeof(struct bk7258_ap_boot_state_s));
166	  bk7258_ap_fault_state()->magic = 0;
167	  bk7258_cpu2_probe_state()->magic = 0;
168	  bk7258_ap_ipi_state()->magic = 0;
169	  bk7258_ap_smp_state()->magic = 0;
170	  state->magic       = BK7258_AP_BOOT_STATE_MAGIC;
171	  state->version     = BK7258_AP_BOOT_STATE_VERSION;
172	  state->size        = sizeof(struct bk7258_ap_boot_state_s);
173	  state->generation  = generation;
174	  state->command     = BK7258_AP_COMMAND_START;
175	  state->state       = BK7258_AP_STATE_STARTING;
176	  state->ram_start   = BK7258_AP_RAM_BASE;
177	  state->ram_end     = BK7258_AP_RAM_BASE + BK7258_AP_RAM_SIZE;
178	  state->flash_start = BK7258_AP_FLASH_ADDR;
179	  state->flash_end   = BK7258_AP_FLASH_ADDR + BK7258_AP_FLASH_SIZE;
180	  __asm volatile ("dmb sy" ::: "memory");
181	}
182	
183	static bool bk7258_ap_scheduler_online(void)
184	{
185	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
186	  volatile struct bk7258_cpu2_probe_state_s *cpu2 =
187	    bk7258_cpu2_probe_state();
188	
189	  __asm volatile ("dmb sy" ::: "memory");
190	  return cpu2->magic == BK7258_CPU2_PROBE_STATE_MAGIC &&
191	         cpu2->version == BK7258_CPU2_PROBE_STATE_VERSION &&
192	         cpu2->size == sizeof(struct bk7258_cpu2_probe_state_s) &&
193	         cpu2->generation == state->generation &&
194	         cpu2->state == BK7258_CPU2_PROBE_STATE_SCHEDULER_ONLINE &&
195	         cpu2->online_mask == 0x3u;
196	}
