198	static int bk7258_ap_wait(uint32_t wanted, uint32_t timeout_ms)
199	{
200	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
201	  uint32_t elapsed;
202	  uint32_t event;
203	  bool first_iter = true; /* TEMP cold-reset diagnostic — guard for W0/W1 */
204	
205	  if (timeout_ms == 0)
206	    {
207	      timeout_ms = BK7258_AP_DEFAULT_TIMEOUT_MS;
208	    }
209	
210	  for (elapsed = 0; elapsed < timeout_ms; elapsed++)
211	    {
212	      event = bk7258_ap_mbox_receive();
213	      if (event != BK7258_AP_EVENT_NONE)
214	        {
215	          state->last_event = event;
216	        }
217	
218	      __asm volatile ("dmb sy" ::: "memory");
219	      if (state->state == wanted)
220	        {
221	          return OK;
222	        }
223	
224	      if (state->state == BK7258_AP_STATE_FAILED)
225	        {
226	          return -EIO;
227	        }
228	
229	      if (first_iter)
230	        {
231	          cold_ckpt("W0"); /* TEMP cold-reset diagnostic — before first sleep */
232	        }
233	
234	      nxsig_usleep(1000);
235	      if (first_iter)
236	        {
237	          cold_ckpt("W1"); /* TEMP cold-reset diagnostic — after first sleep */
238	          first_iter = false;
239	        }
240	    }
241	
242	  return -ETIMEDOUT;
243	}
244	
245	static int bk7258_ap_start_locked(uint32_t timeout_ms)
246	{
247	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
248	  int ret;
249	
250	  cold_ckpt("A0"); /* TEMP cold-reset diagnostic — enter start_locked */
251	
252	  if (state->magic == BK7258_AP_BOOT_STATE_MAGIC &&
253	      (state->state == BK7258_AP_STATE_READY ||
254	       state->state == BK7258_AP_STATE_STARTING))
255	    {
256	      return -EBUSY;
257	    }
258	
259	  /* Hold CPU1 while replacing shared state and the boot address. */
260	
261	  sys_drv_set_cpu1_reset(0);
262	  __asm volatile ("dsb sy; isb sy" ::: "memory");
263	  cold_ckpt("A1"); /* TEMP cold-reset diagnostic — CPU1 reset hold */
264	  bk7258_cpu2_force_reset();
265	  up_mdelay(BK7258_AP_RESTART_DELAY_MS);
266	  cold_ckpt("A2"); /* TEMP cold-reset diagnostic — CPU2 force-reset done */
267	  bk7258_ap_mbox_initialize();
268	  bk7258_ap_state_prepare();
269	  cold_ckpt("A3"); /* TEMP cold-reset diagnostic — mailbox/state prepared */
270	
271	  /* Exact BK7258 CPU1 release order from the CP SDK. */
272	
273	  sys_drv_set_cpu1_pwr_dw(0);
274	  sys_drv_set_cpu1_rxevt_sel(1);
275	  sys_drv_set_cpu1_boot_address_offset(BK7258_AP_FLASH_ADDR >> 8);
276	  __asm volatile ("dsb sy; isb sy" ::: "memory");
277	  cold_ckpt("A4"); /* TEMP cold-reset diagnostic — CPU1 boot addr set */
278	  sys_drv_set_cpu1_reset(1);
279	  __asm volatile ("dsb sy; sev" ::: "memory");
280	  cold_ckpt("A5"); /* TEMP cold-reset diagnostic — CPU1 reset released */
281	  cold_ckpt("A6"); /* TEMP cold-reset diagnostic — entering ap_wait */
282	
283	  ret = bk7258_ap_wait(BK7258_AP_STATE_READY, timeout_ms);
284	  cold_ckpt("A7"); /* TEMP cold-reset diagnostic — ap_wait returned */
285	  if (ret < 0)
286	    {
287	      sys_drv_set_cpu1_reset(0);
288	      __asm volatile ("dsb sy; isb sy" ::: "memory");
289	      bk7258_cpu2_force_reset();
290	      up_mdelay(BK7258_AP_RESTART_DELAY_MS);
291	      cold_ckpt("F1"); /* TEMP cold-reset diagnostic — failure cleanup: cpu2 reset done */
292	      sys_drv_set_cpu1_pwr_dw(1);
293	      cold_ckpt("F2"); /* TEMP cold-reset diagnostic — failure cleanup: cpu1 powered down */
294	
295	      if (state->state != BK7258_AP_STATE_FAILED)
296	        {
297	          state->error = BK7258_AP_ERROR_TIMEOUT;
298	        }
299	
300	      state->command = BK7258_AP_COMMAND_NONE;
301	      state->state = BK7258_AP_STATE_FAILED;
302	      state->last_event = BK7258_AP_EVENT_FAILED;
303	      __asm volatile ("dmb sy" ::: "memory");
304	    }
305	
306	  return ret;
307	}
308	
309	static int bk7258_ap_stop_locked(uint32_t timeout_ms)
310	{
311	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
312	  int ret = OK;
313	
314	  if (bk7258_ap_scheduler_online())
315	    {
316	      return -ENOTSUP;
317	    }
318	
319	  if (state->state == BK7258_AP_STATE_READY ||
320	      state->state == BK7258_AP_STATE_STARTING)
321	    {
322	      state->command = BK7258_AP_COMMAND_STOP;
323	      __asm volatile ("dmb sy" ::: "memory");
324	      bk7258_ap_mbox_send(BK7258_AP_EVENT_STOP);
325	      ret = bk7258_ap_wait(BK7258_AP_STATE_STOPPED, timeout_ms);
326	    }
327	
328	  /* A timeout still ends in a deterministic forced stop of both AP cores. */
329	
330	  sys_drv_set_cpu1_reset(0);

60	  int rxbyte;
